def get_board(board_id, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0243000" if __import__("os").path.isdir("./environment_mix/0243000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            return datetime.datetime.utcfromtimestamp(float(v))
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s2 = s[:-1]
                    dt = datetime.datetime.fromisoformat(s2)
                    return dt
                return datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
        return None

    def _dt_key(v):
        dt = _parse_dt(v)
        if dt is None:
            return datetime.datetime(1970, 1, 1)
        return dt

    def _ensure_log_store():
        # Observability: we maintain a local request log even though not declared as a collection.
        # File name kept stable across tools.
        return "trello_request_log.json"

    def _pick_credential():
        # Ambient auth: choose any available credential context if present.
        # If no auth store exists, proceed as authenticated.
        creds = _load("trello_credentials.json")
        if isinstance(creds, list) and creds:
            for c in creds:
                if isinstance(c, dict) and c.get("status") in (None, "active", "enabled", "valid"):
                    return c.get("id") or c.get("key") or c.get("token") or "cred:unknown"
            c = creds[0]
            if isinstance(c, dict):
                return c.get("id") or c.get("key") or c.get("token") or "cred:unknown"
        return "ambient"

    def _log(endpoint, params, status_code, error_code=None, message=None, selected=None, latency_ms=None):
        fn = _ensure_log_store()
        rows = _load(fn)
        if not isinstance(rows, list):
            rows = []
        row = {
            "id": f"trl_req_{int(time.time()*1000)}",
            "ts": _now(),
            "endpoint": endpoint,
            "credential": _pick_credential(),
            "status": status_code,
            "error_code": error_code,
            "message": message,
            "params": params,
            "selected": selected,
            "latency_ms": latency_ms,
        }
        rows.append(row)
        _save(fn, rows)

    t0 = time.time()
    endpoint = "get_board"

    # Validate input
    if not isinstance(board_id, str):
        _log(endpoint, {"board_id": board_id}, 400, "VALIDATION_ERROR", "board_id must be a string", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "board_id must be a string")
    if not re.match(r"^trl_brd_[0-9A-HJKMNP-TV-Z]{10,}$", board_id):
        _log(endpoint, {"board_id": board_id}, 400, "VALIDATION_ERROR", "board_id does not match required format", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "board_id does not match required format")

    boards = _load("trello_boards.json")
    if not isinstance(boards, list):
        boards = []

    board = None
    for b in boards:
        if isinstance(b, dict) and b.get("id") == board_id:
            board = b
            break

    if board is None:
        _log(endpoint, {"board_id": board_id}, 404, "NOT_FOUND", "Board not found", latency_ms=int((time.time() - t0) * 1000))
        return _err("NOT_FOUND", "Board not found")

    # Access control: not modeled; assume accessible in ambient authenticated context.
    resp = {"board": board}
    _log(endpoint, {"board_id": board_id}, 200, latency_ms=int((time.time() - t0) * 1000))
    return resp

def get_boards(status=None, closed=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0243000" if __import__("os").path.isdir("./environment_mix/0243000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            return datetime.datetime.utcfromtimestamp(float(v))
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s2 = s[:-1]
                    return datetime.datetime.fromisoformat(s2)
                return datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
        return None

    def _dt_key(v):
        dt = _parse_dt(v)
        return dt if dt is not None else datetime.datetime(1970, 1, 1)

    def _ensure_log_store():
        return "trello_request_log.json"

    def _pick_credential():
        creds = _load("trello_credentials.json")
        if isinstance(creds, list) and creds:
            for c in creds:
                if isinstance(c, dict) and c.get("status") in (None, "active", "enabled", "valid"):
                    return c.get("id") or c.get("key") or c.get("token") or "cred:unknown"
            c = creds[0]
            if isinstance(c, dict):
                return c.get("id") or c.get("key") or c.get("token") or "cred:unknown"
        return "ambient"

    def _log(endpoint, params, status_code, error_code=None, message=None, selected=None, latency_ms=None):
        fn = _ensure_log_store()
        rows = _load(fn)
        if not isinstance(rows, list):
            rows = []
        row = {
            "id": f"trl_req_{int(time.time()*1000)}",
            "ts": _now(),
            "endpoint": endpoint,
            "credential": _pick_credential(),
            "status": status_code,
            "error_code": error_code,
            "message": message,
            "params": params,
            "selected": selected,
            "latency_ms": latency_ms,
        }
        rows.append(row)
        _save(fn, rows)

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur.strip():
            return None
        s = cur.strip()
        try:
            raw = base64.urlsafe_b64decode(s.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or obj.get("v") != 1 or "o" not in obj:
                return None
            o = obj["o"]
            if not isinstance(o, int) or o < 0:
                return None
            return o
        except Exception:
            return None

    def _encode_cursor(offset):
        payload = {"v": 1, "o": offset}
        raw = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    t0 = time.time()
    endpoint = "get_boards"

    # Validate inputs
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            _log(endpoint, {"status": status, "closed": closed, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
                 400, "VALIDATION_ERROR", "Invalid status", latency_ms=int((time.time() - t0) * 1000))
            return _err("VALIDATION_ERROR", "Invalid status")
    if closed is not None and not isinstance(closed, bool):
        _log(endpoint, {"status": status, "closed": closed, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
             400, "VALIDATION_ERROR", "closed must be boolean", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "closed must be boolean")
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _log(endpoint, {"status": status, "closed": closed, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
             400, "VALIDATION_ERROR", "limit must be integer", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "limit must be integer")
    if limit < 1 or limit > 200:
        _log(endpoint, {"status": status, "closed": closed, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
             400, "VALIDATION_ERROR", "limit out of range", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "limit out of range")
    if sort_by is None:
        sort_by = "updated_at"
    if sort_by not in ("created_at", "updated_at", "name"):
        _log(endpoint, {"status": status, "closed": closed, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
             400, "VALIDATION_ERROR", "Invalid sort_by", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "Invalid sort_by")
    if sort_order is None:
        sort_order = "desc" if sort_by in ("updated_at", "created_at") else "asc"
    if sort_order not in ("asc", "desc"):
        _log(endpoint, {"status": status, "closed": closed, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
             400, "VALIDATION_ERROR", "Invalid sort_order", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "Invalid sort_order")

    offset = _decode_cursor(cursor)
    if offset is None:
        _log(endpoint, {"status": status, "closed": closed, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
             400, "VALIDATION_ERROR", "Invalid cursor", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "Invalid cursor")

    boards = _load("trello_boards.json")
    if not isinstance(boards, list):
        boards = []

    # Default business rule: exclude deleted unless explicitly requested
    filtered = []
    for b in boards:
        if not isinstance(b, dict):
            continue
        if status is None and b.get("status") == "deleted":
            continue
        if status is not None and b.get("status") != status:
            continue
        if closed is not None and b.get("closed") is not closed:
            continue
        filtered.append(b)

    # Sorting
    reverse = (sort_order == "desc")
    if sort_by in ("created_at", "updated_at"):
        filtered.sort(key=lambda x: _dt_key(x.get(sort_by)), reverse=reverse)
    else:
        filtered.sort(key=lambda x: (x.get("name") or "").lower(), reverse=reverse)

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    resp = {
        "boards": page,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort_by": sort_by,
        "sort_order": sort_order,
    }
    _log(endpoint, {"status": status, "closed": closed, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
         200, latency_ms=int((time.time() - t0) * 1000))
    return resp

