             400, "VALIDATION_ERROR", "Invalid sort_order", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "Invalid sort_order")

    offset = _decode_cursor(cursor)
    if offset is None:
        _log(endpoint, {"board_id": board_id, "status": status, "closed": closed, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
             400, "VALIDATION_ERROR", "Invalid cursor", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "Invalid cursor")

    boards = _load("trello_boards.json")
