    for b in boards:
        if isinstance(b, dict) and b.get("id") == board_id:
            board = b
            break
    if board is None or board.get("status") == "deleted":
        _log(endpoint, {"board_id": board_id, "status": status, "closed": closed, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
             404, "NOT_FOUND", "Board not found", latency_ms=int((time.time() - t0) * 1000))
        return _err("NOT_FOUND", "Board not found")

    lists = _load("trello_lists.json")
