        lists = []

    filtered = []
    for r in lists:
        if not isinstance(r, dict):
            continue
        if r.get("board_id") != board_id:
            continue
        # Default rule: exclude deleted unless explicitly requested
        if status is None and r.get("status") == "deleted":
            continue
        if status is not None and r.get("status") != status:
            continue
        if closed is not None and r.get("closed") is not closed:
            continue
        filtered.append(r)

    reverse = (sort_order == "desc")
