            p = v.get("pos")
            try:
                return float(p)
            except Exception:
                return float("inf")
        filtered.sort(key=_pos, reverse=reverse)
    elif sort_by in ("created_at", "updated_at"):
        filtered.sort(key=lambda x: _dt_key(x.get(sort_by)), reverse=reverse)
    else:
        filtered.sort(key=lambda x: (x.get("name") or "").lower(), reverse=reverse)

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    resp = {
        "board_id": board_id,
        "lists": page,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort_by": sort_by,
        "sort_order": sort_order,
    }
    _log(endpoint, {"board_id": board_id, "status": status, "closed": closed, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order},
         200, latency_ms=int((time.time() - t0) * 1000))
    return resp

def create_list(board_id, name, pos=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0243000" if __import__("os").path.isdir("./environment_mix/0243000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, credential_used=None, detail=None, started=None):
        started = started or time.time()
        latency_ms = int((time.time() - started) * 1000)
        row = {
            "id": "trl_req_" + _gen_token(12),
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": latency_ms,
            "credential": credential_used,
        }
        if detail is not None:
            row["detail"] = detail
        logs = _load("trello_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("trello_request_logs.json", logs)

    def _gen_token(n=12):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return "".join(random.choice(alphabet) for _ in range(n))

    def _gen_id(prefix):
        return prefix + _gen_token(12)

    def _coerce_pos(pos_in, existing_positions):
        # existing_positions: list of numbers
        if pos_in is None or pos_in == "bottom":
            mx = max(existing_positions) if existing_positions else -1
            return float(mx) + 1.0
        if pos_in == "top":
            if not existing_positions:
                return 0.0
            mn = min(existing_positions)
            if mn > 0:
                v = float(mn) - 1.0
                return v if v >= 0 else 0.0
            # mn == 0 => must stay >=0, use fractional to keep ordering
            return 0.5
        # Allow numeric-string per business rules even though tool enum is top/bottom.
        if isinstance(pos_in, str):
            try:
                v = float(pos_in)
            except ValueError:
                raise ValueError("pos")
            if v < 0:
                raise ValueError("pos_range")
            return v
        raise ValueError("pos")

    started = time.time()
    endpoint = "create_list"

    # Validate inputs
    if not isinstance(board_id, str) or not re.match(r"^trl_brd_[0-9A-HJKMNP-TV-Z]{10,}$", board_id):
        err = _err("VALIDATION_ERROR", "board_id is invalid", field="board_id")
        _log(endpoint, "error", detail=err, started=started)
        return err
    if not isinstance(name, str) or len(name.strip()) < 1:
        err = _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")
        _log(endpoint, "error", detail=err, started=started)
        return err
    if pos is not None and not isinstance(pos, str):
        err = _err("VALIDATION_ERROR", "pos must be a string", field="pos")
        _log(endpoint, "error", detail=err, started=started)
        return err
    if isinstance(pos, str) and pos not in ("top", "bottom"):
        # tool says enum, but business rules allow numeric-string too; accept numeric-strings
        try:
            float(pos)
        except ValueError:
            err = _err("VALIDATION_ERROR", "pos must be 'top', 'bottom', or a numeric string", field="pos")
            _log(endpoint, "error", detail=err, started=started)
            return err

    boards = _load("trello_boards.json")
    if not isinstance(boards, list):
        boards = []
    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board or board.get("status") == "deleted":
        err = _err("NOT_FOUND", "board not found", board_id=board_id)
        _log(endpoint, "error", detail=err, started=started)
        return err
    # "FORBIDDEN" in tool description; only allowed error codes list doesn't include it.
    # In this datastore model there is no auth/ACL, so we treat as authorized.

    lists = _load("trello_lists.json")
    if not isinstance(lists, list):
        lists = []

    # Enforce unique(board_id, name) where status <> 'deleted'
    for lst in lists:
        if lst.get("board_id") == board_id and lst.get("status") != "deleted" and lst.get("name") == name.strip():
            err = _err("CONFLICT", "a non-deleted list with this name already exists on the board",
                       board_id=board_id, name=name.strip())
            _log(endpoint, "error", detail=err, started=started)
            return err

    existing_positions = [float(x.get("pos", 0)) for x in lists if x.get("board_id") == board_id and x.get("status") != "deleted"]
    try:
        computed_pos = _coerce_pos(pos, existing_positions)
    except ValueError as e:
        code = str(e)
        if code in ("pos", "pos_range"):
            msg = "pos is invalid" if code == "pos" else "pos must be >= 0"
            err = _err("VALIDATION_ERROR", msg, field="pos")
            _log(endpoint, "error", detail=err, started=started)
            return err
        err = _err("VALIDATION_ERROR", "pos is invalid", field="pos")
        _log(endpoint, "error", detail=err, started=started)
        return err

    if computed_pos < 0:
        err = _err("VALIDATION_ERROR", "pos must be >= 0", field="pos")
        _log(endpoint, "error", detail=err, started=started)
        return err

    # Enforce lifecycle/closed consistency for new list
    now = _now()
    new_row = {
        "id": _gen_id("trl_lst_"),
        "trello_id": _gen_id("trello_lst_"),  # mirrored placeholder; must be unique locally
        "board_id": board_id,
        "name": name.strip(),
        "pos": computed_pos,
        "closed": False,
        "status": "open",
        "created_at": now,
        "updated_at": now,
    }

    # unique(trello_id)
    trello_ids = {x.get("trello_id") for x in lists if isinstance(x, dict)}
    while new_row["trello_id"] in trello_ids:
        new_row["trello_id"] = _gen_id("trello_lst_")

    lists.append(new_row)
    _save("trello_lists.json", lists)

    # Update board updated_at (mirroring typical behavior) and enforce board constraints
    board["updated_at"] = now
    _save("trello_boards.json", boards)

    resp = {"list": new_row}
    _log(endpoint, "ok", detail={"created_id": new_row["id"], "board_id": board_id}, started=started)
    return resp

