    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_cards"
    status = "ok"

    # Rate/quota + request log (best-effort if collection absent)
    logs = _load("trello_request_logs.json")
    usage = _load("trello_usage.json")

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _get_usage_row():
        if isinstance(usage, list) and usage:
            if isinstance(usage[0], dict):
                return usage[0]
        return None

    def _enforce_limits():
        nonlocal logs, usage
        # Defaults if not configured
        per_min = None
        per_day = None
        u = _get_usage_row()
        if u:
            per_min = u.get("rate_limit_per_minute", u.get("per_minute"))
            per_day = u.get("quota_per_day", u.get("per_day"))
        now = datetime.datetime.now(datetime.timezone.utc)
        if per_min is not None:
            try:
                lim = int(per_min)
                if lim >= 0:
                    cutoff = now - datetime.timedelta(minutes=1)
                    cnt = 0
                    for r in (logs if isinstance(logs, list) else []):
                        ts = r.get("timestamp") if isinstance(r, dict) else None
                        if not ts:
                            continue
                        try:
                            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                        except Exception:
                            continue
                        if dt >= cutoff:
                            cnt += 1
                    if cnt >= lim:
                        return _err("RATE_LIMIT", "Rate limit exceeded.")
            except Exception:
                pass
        if per_day is not None:
            try:
                lim = int(per_day)
                if lim >= 0:
                    cutoff = now - datetime.timedelta(days=1)
                    cnt = 0
                    for r in (logs if isinstance(logs, list) else []):
                        ts = r.get("timestamp") if isinstance(r, dict) else None
                        if not ts:
                            continue
                        try:
                            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                        except Exception:
                            continue
                        if dt >= cutoff:
                            cnt += 1
                    if cnt >= lim:
                        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
            except Exception:
                pass
        return None

    def _log_call(ok, extra=None):
        nonlocal logs, usage
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"trl_req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "latency_ms": latency_ms,
            "status": "ok" if ok else "error",
        }
        if extra and isinstance(extra, dict):
            row.update(extra)
        if isinstance(logs, list):
            logs.append(row)
            _save("trello_request_logs.json", logs)
        # Increment counters if present
        if isinstance(usage, list) and usage and isinstance(usage[0], dict):
            u0 = usage[0]
            u0["total_requests"] = int(u0.get("total_requests", 0)) + 1
            if ok:
                u0["total_success"] = int(u0.get("total_success", 0)) + 1
            else:
                u0["total_errors"] = int(u0.get("total_errors", 0)) + 1
            _save("trello_usage.json", usage)

    limit_err = _enforce_limits()
    if limit_err:
        _log_call(False, {"error_code": limit_err["error"]["code"]})
        return limit_err

    # Validate list_id
    if not isinstance(list_id, str):
        e = _err("VALIDATION_ERROR", "list_id must be a string.")
        _log_call(False, {"error_code": e["error"]["code"]})
        return e
    if not re.match(r"^trl_lst_[0-9A-HJKMNP-TV-Z]{10,}$", list_id):
        e = _err("VALIDATION_ERROR", "list_id is not a valid Trello list ID.", field="list_id")
        _log_call(False, {"error_code": e["error"]["code"]})
        return e

    lists = _load("trello_lists.json")
    cards = _load("trello_cards.json")

    lst = None
    for r in (lists if isinstance(lists, list) else []):
        if isinstance(r, dict) and r.get("id") == list_id:
            lst = r
            break
    if not lst:
        e = _err("NOT_FOUND", "List not found.", list_id=list_id)
        _log_call(False, {"error_code": e["error"]["code"]})
        return e
    if lst.get("status") == "deleted":
        e = _err("NOT_FOUND", "List not found.", list_id=list_id)
        _log_call(False, {"error_code": e["error"]["code"]})
        return e

    # Return cards for list_id where status <> 'deleted', ordered by pos asc
    out = []
    for c in (cards if isinstance(cards, list) else []):
        if not isinstance(c, dict):
            continue
        if c.get("list_id") == list_id and c.get("status") != "deleted":
            out.append(c)
    try:
        out.sort(key=lambda x: (float(x.get("pos", 0)), str(x.get("id", ""))))
    except Exception:
        out.sort(key=lambda x: str(x.get("id", "")))

    resp = {
        "cards": out,
        "list_id": list_id,
        "total": len(out),
    }
    _log_call(True, {"result_count": len(out)})
    return resp

