    t0 = time.time()
    endpoint = "update_card"

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _gen_id(prefix):
        ts = int(time.time() * 1000)
        r = random.getrandbits(80)
        def enc(v, n):
            s = []
            for _ in range(n):
                s.append(_B32[v & 31])
                v >>= 5
            return "".join(reversed(s))
        return prefix + enc(ts, 10) + enc(r, 16)

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        v = s.strip()
        if not v:
            return None
        # Accept ...Z or offset; store normalized with Z if UTC
        try:
            if v.endswith("Z"):
                dt = datetime.datetime.fromisoformat(v[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(v)
            if dt.tzinfo is None:
                # treat naive as UTC
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            dt_utc = dt.astimezone(datetime.timezone.utc).replace(microsecond=0)
            return dt_utc.isoformat().replace("+00:00", "Z")
        except ValueError:
            return None

    def _log(status, message=None, **extra):
