        usage = _load("trello_usage.json")
        if not isinstance(usage, list) or not usage:
            return None
        cfg = usage[0] if isinstance(usage[0], dict) else {}
        per_min = cfg.get("rate_limit_per_minute", cfg.get("per_minute"))
        per_day = cfg.get("quota_per_day", cfg.get("per_day"))
        logs = _load("trello_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        if per_min is not None:
            try:
                lim = int(per_min)
                cutoff = now - datetime.timedelta(minutes=1)
                cnt = 0
                for r in logs:
                    if not isinstance(r, dict):
                        continue
                    ts = r.get("timestamp") or r.get("ts")
                    if not isinstance(ts, str):
                        continue
                    try:
                        if ts.endswith("Z"):
                            dt = datetime.datetime.fromisoformat(ts[:-1] + "+00:00")
                        else:
                            dt = datetime.datetime.fromisoformat(ts)
                        if dt.tzinfo is None:
                            dt = dt.replace(tzinfo=datetime.timezone.utc)
                    except ValueError:
                        continue
                    if dt >= cutoff:
                        cnt += 1
                if cnt >= lim:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")
            except Exception:
                pass
        if per_day is not None:
            try:
                lim = int(per_day)
                cutoff = now - datetime.timedelta(days=1)
                cnt = 0
                for r in logs:
                    if not isinstance(r, dict):
                        continue
                    ts = r.get("timestamp") or r.get("ts")
                    if not isinstance(ts, str):
                        continue
                    try:
                        if ts.endswith("Z"):
                            dt = datetime.datetime.fromisoformat(ts[:-1] + "+00:00")
                        else:
                            dt = datetime.datetime.fromisoformat(ts)
                        if dt.tzinfo is None:
                            dt = dt.replace(tzinfo=datetime.timezone.utc)
                    except ValueError:
                        continue
                    if dt >= cutoff:
                        cnt += 1
                if cnt >= lim:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
            except Exception:
                pass
        return None

    lim_err = _enforce_limits()
    if lim_err:
        _log("RATE_LIMIT" if lim_err["error"]["code"] == "RATE_LIMIT" else "QUOTA_EXCEEDED", lim_err["error"]["message"])
        return lim_err

    # Validate required
    if not isinstance(card_id, str) or not re.match(r"^trl_crd_[0-9A-HJKMNP-TV-Z]{10,}$", card_id):
        _log("VALIDATION_ERROR", "card_id is not a valid card ID", field="card_id", card_id=card_id)
        return _err("VALIDATION_ERROR", "card_id is not a valid card ID", field="card_id")

    # Validate updatable fields presence
    if all(v is None for v in (name, desc, pos, due_at, closed, status, list_id)):
        _log("VALIDATION_ERROR", "No updatable fields provided")
        return _err("VALIDATION_ERROR", "No updatable fields provided")

    # Type validations
    if name is not None:
        if not isinstance(name, str) or name.strip() == "":
            _log("VALIDATION_ERROR", "name must be a non-empty string", field="name")
            return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")
        name = name.strip()

    if desc is not None and not isinstance(desc, str):
        _log("VALIDATION_ERROR", "desc must be a string", field="desc")
        return _err("VALIDATION_ERROR", "desc must be a string", field="desc")

    if pos is not None:
        if not isinstance(pos, (int, float)) or isinstance(pos, bool):
            _log("VALIDATION_ERROR", "pos must be a number", field="pos")
            return _err("VALIDATION_ERROR", "pos must be a number", field="pos")
        if pos < 0:
            _log("VALIDATION_ERROR", "pos must be >= 0", field="pos")
            return _err("VALIDATION_ERROR", "pos must be >= 0", field="pos")

    parsed_due = None
    if due_at is not None:
        parsed_due = _parse_iso_dt(due_at)
        if parsed_due is None:
            _log("VALIDATION_ERROR", "due_at must be an ISO 8601 date-time string", field="due_at")
            return _err("VALIDATION_ERROR", "due_at must be an ISO 8601 date-time string", field="due_at")

    if closed is not None and not isinstance(closed, bool):
        _log("VALIDATION_ERROR", "closed must be boolean", field="closed")
        return _err("VALIDATION_ERROR", "closed must be boolean", field="closed")

    if status is not None:
        if not isinstance(status, str) or status not in ("open", "archived", "deleted"):
            _log("VALIDATION_ERROR", "status must be one of: open, archived, deleted", field="status")
            return _err("VALIDATION_ERROR", "status must be one of: open, archived, deleted", field="status")

    if list_id is not None:
        if not isinstance(list_id, str) or not re.match(r"^trl_lst_[0-9A-HJKMNP-TV-Z]{10,}$", list_id):
            _log("VALIDATION_ERROR", "list_id is not a valid list ID", field="list_id")
            return _err("VALIDATION_ERROR", "list_id is not a valid list ID", field="list_id")

    cards = _load("trello_cards.json")
    if not isinstance(cards, list):
        cards = []
    card_idx = None
    card = None
    for i, r in enumerate(cards):
        if isinstance(r, dict) and r.get("id") == card_id:
            card_idx = i
            card = r
            break
    if card is None:
        _log("NOT_FOUND", "Card not found", card_id=card_id)
        return _err("NOT_FOUND", "Card not found", card_id=card_id)

    # Validate current state modifiability: allow updates when open/archived; deleted cannot be modified
    if card.get("status") == "deleted":
        _log("CONFLICT", "Card is deleted and cannot be modified", card_id=card_id)
        return _err("CONFLICT", "Card is deleted and cannot be modified", card_id=card_id)

    lists = _load("trello_lists.json")
    if not isinstance(lists, list):
        lists = []
    # Determine destination list
    dest_list_id = list_id if list_id is not None else card.get("list_id")
    dest_list = next((l for l in lists if isinstance(l, dict) and l.get("id") == dest_list_id), None)
    if dest_list is None:
        _log("NOT_FOUND", "Destination list not found", field="list_id", list_id=dest_list_id)
        return _err("NOT_FOUND", "Destination list not found", field="list_id", list_id=dest_list_id)
    if dest_list.get("status") == "deleted":
        _log("CONFLICT", "Destination list is deleted", field="list_id", list_id=dest_list_id)
        return _err("CONFLICT", "Destination list is deleted", field="list_id", list_id=dest_list_id)

    # Lifecycle transitions rules
    transitions = {"open": ("archived", "deleted"), "archived": ("open", "deleted"), "deleted": ()}
    cur_status = card.get("status")
    target_status = cur_status

    # Apply status first if provided
    if status is not None and status != cur_status:
        if cur_status not in transitions or status not in transitions[cur_status]:
            _log("INVALID_TRANSITION", "Illegal status transition", from_status=cur_status, to_status=status)
            return _err("INVALID_TRANSITION", f"Illegal status transition from '{cur_status}' to '{status}'", field="status")
        target_status = status

    # closed->status coupling (relaxed to accept valid request): if closed=true, server must ensure status archived unless deleted.
    # If caller explicitly requests status='open' with closed=true, we coerce to archived (legal transition) rather than rejecting.
    target_closed = card.get("closed")
    if closed is not None:
        target_closed = closed

    # If closing, force status archived unless already deleted target
    if target_closed is True and target_status != "deleted":
        if target_status == "open":
            # need transition open->archived
            if cur_status == "open":
                target_status = "archived"
            elif cur_status == "archived":
                target_status = "archived"
            else:
                # cannot revive deleted
                _log("CONFLICT", "Cannot archive a deleted card", card_id=card_id)
                return _err("CONFLICT", "Cannot modify a deleted card", card_id=card_id)

    # If reopening (closed=false), force status open (unless deleted)
    if target_closed is False and target_status != "deleted":
        if target_status == "archived":
            # allow setting closed=false but keeping archived? business rule: closed=false implies status='open'
            # Coerce to open if legal.
            if cur_status == "archived":
                target_status = "open"
            elif cur_status == "open":
                target_status = "open"

    # Ensure computed transition is legal from current status
    if target_status != cur_status:
        if cur_status not in transitions or target_status not in transitions[cur_status]:
            _log("INVALID_TRANSITION", "Illegal status transition (computed)", from_status=cur_status, to_status=target_status)
            return _err("INVALID_TRANSITION", f"Illegal status transition from '{cur_status}' to '{target_status}'", field="status")

    # Apply updates
    updated = dict(card)
    if name is not None:
        updated["name"] = name
    if desc is not None:
        updated["desc"] = desc
    if parsed_due is not None:
        updated["due_at"] = parsed_due
    if due_at is not None and parsed_due is None:
        # unreachable due to validation; keep for safety
        pass
    if closed is not None:
        updated["closed"] = target_closed
    else:
        updated["closed"] = target_closed
    if list_id is not None:
        updated["list_id"] = dest_list_id
    if pos is not None:
        updated["pos"] = float(pos) if isinstance(pos, int) else pos
    # Ensure pos >=0 stored
    if updated.get("pos") is None:
        updated["pos"] = 0
    try:
        if float(updated.get("pos")) < 0:
            _log("VALIDATION_ERROR", "pos must be >= 0", field="pos")
            return _err("VALIDATION_ERROR", "pos must be >= 0", field="pos")
    except Exception:
        _log("VALIDATION_ERROR", "pos must be a number", field="pos")
        return _err("VALIDATION_ERROR", "pos must be a number", field="pos")

    updated["status"] = target_status
    # Enforce coupling: closed flag consistent with status
    if updated["status"] == "open":
        updated["closed"] = False
    elif updated["status"] in ("archived", "deleted"):
        # allow closed True for archived/deleted
        updated["closed"] = True if updated.get("closed") is not False else True

    updated["updated_at"] = _now_iso()

    cards[card_idx] = updated
    _save("trello_cards.json", cards)
    _log("OK", "updated", card_id=card_id)
    return {"card": updated}

def delete_card(card_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0243000" if __import__("os").path.isdir("./environment_mix/0243000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete_card"

    logs = _load("trello_request_logs.json")
    usage = _load("trello_usage.json")

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _get_usage_row():
        if isinstance(usage, list) and usage and isinstance(usage[0], dict):
            return usage[0]
        return None

    def _enforce_limits():
        nonlocal logs, usage
        u = _get_usage_row()
        per_min = u.get("rate_limit_per_minute", u.get("per_minute")) if u else None
        per_day = u.get("quota_per_day", u.get("per_day")) if u else None
        now = datetime.datetime.now(datetime.timezone.utc)
        if per_min is not None:
            try:
                lim = int(per_min)
                cutoff = now - datetime.timedelta(minutes=1)
                cnt = 0
                for r in (logs if isinstance(logs, list) else []):
                    if not isinstance(r, dict):
                        continue
                    ts = r.get("timestamp")
                    if not ts:
                        continue
                    try:
                        dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    except Exception:
                        continue
                    if dt >= cutoff:
                        cnt += 1
                if cnt >= lim:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")
            except Exception:
                pass
        if per_day is not None:
            try:
                lim = int(per_day)
                cutoff = now - datetime.timedelta(days=1)
                cnt = 0
                for r in (logs if isinstance(logs, list) else []):
                    if not isinstance(r, dict):
                        continue
                    ts = r.get("timestamp")
                    if not ts:
                        continue
                    try:
                        dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    except Exception:
                        continue
                    if dt >= cutoff:
                        cnt += 1
                if cnt >= lim:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
            except Exception:
                pass
        return None

    def _log_call(ok, extra=None):
        nonlocal logs, usage
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"trl_req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "latency_ms": latency_ms,
            "status": "ok" if ok else "error",
        }
        if extra and isinstance(extra, dict):
            row.update(extra)
        if isinstance(logs, list):
            logs.append(row)
            _save("trello_request_logs.json", logs)
        if isinstance(usage, list) and usage and isinstance(usage[0], dict):
            u0 = usage[0]
            u0["total_requests"] = int(u0.get("total_requests", 0)) + 1
            if ok:
                u0["total_success"] = int(u0.get("total_success", 0)) + 1
            else:
                u0["total_errors"] = int(u0.get("total_errors", 0)) + 1
            _save("trello_usage.json", usage)

    limit_err = _enforce_limits()
    if limit_err:
        _log_call(False, {"error_code": limit_err["error"]["code"]})
        return limit_err

    if not isinstance(card_id, str):
        e = _err("VALIDATION_ERROR", "card_id must be a string.", field="card_id")
        _log_call(False, {"error_code": e["error"]["code"]})
        return e
    if not re.match(r"^trl_crd_[0-9A-HJKMNP-TV-Z]{10,}$", card_id):
        e = _err("VALIDATION_ERROR", "card_id is not a valid Trello card ID.", field="card_id")
        _log_call(False, {"error_code": e["error"]["code"]})
        return e

    cards = _load("trello_cards.json")
    if not isinstance(cards, list):
        cards = []

    idx = None
    card = None
    for i, c in enumerate(cards):
        if isinstance(c, dict) and c.get("id") == card_id:
            idx = i
            card = c
            break
    if card is None:
        e = _err("NOT_FOUND", "Card not found.", card_id=card_id)
        _log_call(False, {"error_code": e["error"]["code"]})
        return e

    if card.get("status") == "deleted":
        e = _err("CONFLICT", "Card is already deleted.", card_id=card_id)
        _log_call(False, {"error_code": e["error"]["code"]})
        return e

    # Transition to deleted from open/archived only
    cur_status = card.get("status")
    transitions = {"open": {"archived", "deleted"}, "archived": {"open", "deleted"}, "deleted": set()}
    if cur_status not in transitions:
        e = _err("CONFLICT", "Card cannot be deleted from its current state.", status=cur_status)
        _log_call(False, {"error_code": e["error"]["code"]})
        return e
    if "deleted" not in transitions[cur_status]:
        e = _err("INVALID_TRANSITION", f"Cannot transition card status from {cur_status} to deleted.",
                 from_status=cur_status, to_status="deleted")
        _log_call(False, {"error_code": e["error"]["code"]})
        return e

    card["status"] = "deleted"
    card["closed"] = True
    card["updated_at"] = _now_iso()
    cards[idx] = card
    _save("trello_cards.json", cards)

    resp = {
        "deleted": True,
        "card_id": card_id,
        "status": card["status"],
        "updated_at": card["updated_at"],
    }
    _log_call(True, {"card_id": card_id})
    return resp

def get_checklist(checklist_id, **_extra):
    import json, os, datetime, re, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0243000" if __import__("os").path.isdir("./environment_mix/0243000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_checklist"

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _gen_id(prefix):
        ts = int(time.time() * 1000)
        r = random.getrandbits(80)
        def enc(v, n):
            s = []
            for _ in range(n):
                s.append(_B32[v & 31])
                v >>= 5
            return "".join(reversed(s))
        return prefix + enc(ts, 10) + enc(r, 16)

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, message=None, **extra):
        logs = _load("trello_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_id("trl_req_"),
            "endpoint": endpoint,
            "status": status,
            "message": message,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        row.update(extra)
        logs.append(row)
        _save("trello_request_logs.json", logs)

    try:
        if not isinstance(checklist_id, str) or not re.match(r"^trl_chk_[0-9A-HJKMNP-TV-Z]{10,}$", checklist_id):
            _log("VALIDATION_ERROR", "checklist_id is not a valid checklist ID", field="checklist_id")
            return _err("VALIDATION_ERROR", "checklist_id is not a valid checklist ID", field="checklist_id")

        checklists = _load("trello_checklists.json")
        if not isinstance(checklists, list):
            checklists = []
        checklist = next((c for c in checklists if isinstance(c, dict) and c.get("id") == checklist_id), None)
        if not checklist:
            _log("NOT_FOUND", "Checklist not found", checklist_id=checklist_id)
            return _err("NOT_FOUND", "Checklist not found", checklist_id=checklist_id)

        # FK integrity: checklist must reference a real card (but a deleted parent is NOT a reason to 404).
        cards = _load("trello_cards.json")
        if not isinstance(cards, list):
            cards = []
        card_id = checklist.get("card_id")
        card = next((c for c in cards if isinstance(c, dict) and c.get("id") == card_id), None)
        if not card:
            _log("NOT_FOUND", "Parent card not found for checklist", checklist_id=checklist_id, card_id=card_id)
            return _err("NOT_FOUND", "Parent card not found for checklist", checklist_id=checklist_id, card_id=card_id)

        # Include items as stored in the mirror. If checklist is deleted, return it but with no operable items.
        items = _load("trello_checkitems.json")
        if not isinstance(items, list):
            items = []
        checklist_items = [it for it in items if isinstance(it, dict) and it.get("checklist_id") == checklist_id]
        checklist_items.sort(key=lambda r: (float(r.get("pos", 0.0)) if isinstance(r.get("pos"), (int, float)) and not isinstance(r.get("pos"), bool) else 0.0, r.get("created_at", ""), r.get("id", "")))

        if checklist.get("status") == "deleted":
            checklist_items = [it for it in checklist_items if it.get("status") == "deleted"]

        out = dict(checklist)
        out["items"] = checklist_items

        _log("OK", None, checklist_id=checklist_id, card_id=card_id)
        return {"checklist": out}
    except Exception as e:
        _log("INTERNAL_ERROR", "Unexpected server error", detail=str(e))
        return _err("CONFLICT", "Unexpected server error", detail=str(e))

def get_card_checklists(card_id, **_extra):
