def create_checklist(card_id, name, pos=None, **_extra):
    import json, os, datetime, re, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0243000" if __import__("os").path.isdir("./environment_mix/0243000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_checklist"

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _gen_id(prefix):
        ts = int(time.time() * 1000)
        r = random.getrandbits(80)
        def enc(v, n):
            s = []
            for _ in range(n):
                s.append(_B32[v & 31])
                v >>= 5
            return "".join(reversed(s))
        return prefix + enc(ts, 10) + enc(r, 16)

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, message=None, **extra):
        logs = _load("trello_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_id("trl_req_"),
            "endpoint": endpoint,
            "status": status,
            "message": message,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        row.update(extra)
        logs.append(row)
        _save("trello_request_logs.json", logs)

    def _compute_pos(existing, req_pos):
        # existing: list of numeric pos
        nums = []
        for p in existing:
            try:
                nums.append(float(p))
            except Exception:
                pass
        if req_pos is None or (isinstance(req_pos, str) and req_pos.strip() == ""):
            return (max(nums) + 1.0) if nums else 0.0
        if isinstance(req_pos, (int, float)) and not isinstance(req_pos, bool):
            # accept numeric even if schema says string (relax per audit)
            if float(req_pos) < 0:
                return None
            return float(req_pos)
        if not isinstance(req_pos, str):
            return None
        v = req_pos.strip().lower()
        if v == "bottom":
            return (max(nums) + 1.0) if nums else 0.0
        if v == "top":
            if not nums:
                return 0.0
            mn = min(nums)
            candidate = mn - 1.0
            if candidate >= 0:
                return candidate
            # cannot go below 0: use fractional >0 to keep ordering while pos>=0
            return 0.5 if mn == 0 else max(0.0, mn / 2.0)
        # numeric string
        try:
            f = float(req_pos)
            if f < 0:
                return None
            return f
        except ValueError:
            return None

    # Validate
    if not isinstance(card_id, str) or not re.match(r"^trl_crd_[0-9A-HJKMNP-TV-Z]{10,}$", card_id):
        _log("VALIDATION_ERROR", "card_id is not a valid card ID", field="card_id")
        return _err("VALIDATION_ERROR", "card_id is not a valid card ID", field="card_id")

    if not isinstance(name, str) or name.strip() == "":
        _log("VALIDATION_ERROR", "name must be a non-empty string", field="name")
        return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")
    name = name.strip()

    cards = _load("trello_cards.json")
    if not isinstance(cards, list):
        cards = []
    card = next((c for c in cards if isinstance(c, dict) and c.get("id") == card_id), None)
    if not card:
        _log("NOT_FOUND", "Card not found", card_id=card_id)
        return _err("NOT_FOUND", "Card not found", card_id=card_id)
    if card.get("status") == "deleted":
        _log("CONFLICT", "Cannot add checklist to deleted card", card_id=card_id)
        return _err("CONFLICT", "Cannot add checklist to deleted card", card_id=card_id)

    checklists = _load("trello_checklists.json")
    if not isinstance(checklists, list):
        checklists = []
    # uniqueness per card among active checklists
    for c in checklists:
        if not isinstance(c, dict):
            continue
        if c.get("card_id") == card_id and c.get("status") == "active" and isinstance(c.get("name"), str) and c.get("name") == name:
            _log("CONFLICT", "Checklist name must be unique per card among active checklists", field="name")
            return _err("CONFLICT", "Checklist name must be unique per card among active checklists", field="name")

    existing_pos = [c.get("pos") for c in checklists if isinstance(c, dict) and c.get("card_id") == card_id and c.get("status") != "deleted"]
    computed = _compute_pos(existing_pos, pos)
    if computed is None:
        _log("VALIDATION_ERROR", "pos must be 'top', 'bottom', or a non-negative number (string or number)", field="pos")
        return _err("VALIDATION_ERROR", "pos must be 'top', 'bottom', or a non-negative number (string or number)", field="pos")
    if computed < 0:
        _log("VALIDATION_ERROR", "pos must be >= 0", field="pos")
        return _err("VALIDATION_ERROR", "pos must be >= 0", field="pos")

    now = _now_iso()
    new_row = {
        "id": _gen_id("trl_chk_"),
        "trello_id": _gen_id("tchk_"),
        "card_id": card_id,
        "name": name,
        "pos": computed,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }
    checklists.append(new_row)
    _save("trello_checklists.json", checklists)
    _log("OK", "created", checklist_id=new_row["id"], card_id=card_id)
    return {"checklist": new_row}

