            "latency_ms": int((time.time() - t0) * 1000),
        }
        row.update(extra)
        logs.append(row)
        _save("trello_request_logs.json", logs)

    def _compute_pos(existing_positions, req_pos):
        nums = []
        for p in existing_positions:
            if isinstance(p, (int, float)) and not isinstance(p, bool):
                nums.append(float(p))
            else:
                try:
                    nums.append(float(p))
                except Exception:
                    pass

        if req_pos is None:
            return None

        # Tool schema says string, but audit shows numeric used: accept both.
        if isinstance(req_pos, (int, float)) and not isinstance(req_pos, bool):
            f = float(req_pos)
            if f < 0:
                return None
            return f

        if not isinstance(req_pos, str):
            return None
        v = req_pos.strip().lower()
        if v == "bottom":
            return (max(nums) + 1.0) if nums else 0.0
        if v == "top":
            if not nums:
                return 0.0
            mn = min(nums)
            candidate = mn - 1.0
            if candidate >= 0:
                return candidate
            # must not go < 0
            return 0.5 if mn == 0 else max(0.0, mn / 2.0)
        try:
            f = float(v)
            if f < 0:
                return None
            return f
        except Exception:
            return None

    try:
        if not isinstance(checklist_id, str) or not re.match(r"^trl_chk_[0-9A-HJKMNP-TV-Z]{10,}$", checklist_id):
            _log("VALIDATION_ERROR", "checklist_id is not a valid checklist ID", field="checklist_id")
            return _err("VALIDATION_ERROR", "checklist_id is not a valid checklist ID", field="checklist_id")

        if name is None and pos is None:
            _log("VALIDATION_ERROR", "No updatable fields provided")
            return _err("VALIDATION_ERROR", "No updatable fields provided")

        if name is not None:
            if not isinstance(name, str) or name.strip() == "":
                _log("VALIDATION_ERROR", "name must be a non-empty string", field="name")
                return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")
            name = name.strip()

        checklists = _load("trello_checklists.json")
        if not isinstance(checklists, list):
            checklists = []
        idx = None
        chk = None
        for i, r in enumerate(checklists):
            if isinstance(r, dict) and r.get("id") == checklist_id:
                idx = i
                chk = r
                break
        if chk is None:
            _log("NOT_FOUND", "Checklist not found", checklist_id=checklist_id)
            return _err("NOT_FOUND", "Checklist not found", checklist_id=checklist_id)

        if chk.get("status") == "deleted":
            _log("CONFLICT", "Checklist is deleted and cannot be modified", checklist_id=checklist_id)
            return _err("CONFLICT", "Checklist is deleted and cannot be modified", checklist_id=checklist_id)

        # FK integrity: must have a real parent card, but parent being deleted is NOT a conflict for updating
        # unless explicitly required. Business rules only block operations when checklist itself is deleted.
        cards = _load("trello_cards.json")
        if not isinstance(cards, list):
            cards = []
        card_id = chk.get("card_id")
        card = next((c for c in cards if isinstance(c, dict) and c.get("id") == card_id), None)
        if not card:
            _log("NOT_FOUND", "Parent card not found for checklist", checklist_id=checklist_id, card_id=card_id)
            return _err("NOT_FOUND", "Parent card not found for checklist", checklist_id=checklist_id, card_id=card_id)

        # Uniqueness per card among active checklists
        if name is not None:
            for other in checklists:
                if not isinstance(other, dict):
                    continue
                if other.get("id") == checklist_id:
                    continue
                if other.get("card_id") == card_id and other.get("status") != "deleted" and other.get("name") == name:
                    _log("CONFLICT", "Checklist name must be unique per card among active checklists", checklist_id=checklist_id, card_id=card_id, name=name)
                    return _err("CONFLICT", "Checklist name must be unique per card among active checklists", checklist_id=checklist_id, card_id=card_id, name=name)

        # Compute pos if requested
        if pos is not None:
            existing = [c.get("pos") for c in checklists if isinstance(c, dict) and c.get("card_id") == card_id and c.get("status") != "deleted" and c.get("id") != checklist_id]
            new_pos = _compute_pos(existing, pos)
            if new_pos is None:
                _log("VALIDATION_ERROR", "pos must be 'top', 'bottom', or a non-negative number", field="pos")
                return _err("VALIDATION_ERROR", "pos must be 'top', 'bottom', or a non-negative number", field="pos")
        else:
            new_pos = None

        updated = dict(chk)
        if name is not None:
            updated["name"] = name
        if new_pos is not None:
            updated["pos"] = new_pos
        updated["updated_at"] = _now_iso()

        checklists[idx] = updated
        _save("trello_checklists.json", checklists)

        # Return updated checklist including its items as stored
        items = _load("trello_checkitems.json")
        if not isinstance(items, list):
            items = []
        checklist_items = [it for it in items if isinstance(it, dict) and it.get("checklist_id") == checklist_id]
        checklist_items.sort(key=lambda r: (float(r.get("pos", 0.0)) if isinstance(r.get("pos"), (int, float)) and not isinstance(r.get("pos"), bool) else 0.0, r.get("created_at", ""), r.get("id", "")))

        out = dict(updated)
        out["items"] = checklist_items

        _log("OK", None, checklist_id=checklist_id, card_id=card_id)
        return {"checklist": out}
    except Exception as e:
        _log("INTERNAL_ERROR", "Unexpected server error", detail=str(e))
        return _err("CONFLICT", "Unexpected server error", detail=str(e))

