                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_checkitem"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, message=None, **extra):
        # best-effort logging; do not fail the endpoint if logging fails
        try:
            logs = _load("trello_request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "id": f"trl_req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "status": status,
                "message": message,
                "timestamp": _now_iso(),
                "latency_ms": int((time.time() - t0) * 1000),
            }
            row.update(extra)
            logs.append(row)
            _save("trello_request_logs.json", logs)
        except Exception:
            pass

    try:
        # Validate required inputs
        if not isinstance(checklist_id, str) or not checklist_id:
            _log("VALIDATION_ERROR", "checklist_id must be a non-empty string", field="checklist_id")
            return _err("VALIDATION_ERROR", "checklist_id must be a non-empty string", field="checklist_id")
        if not isinstance(checkitem_id, str) or not checkitem_id:
            _log("VALIDATION_ERROR", "checkitem_id must be a non-empty string", field="checkitem_id")
            return _err("VALIDATION_ERROR", "checkitem_id must be a non-empty string", field="checkitem_id")

        # Enforce declared format (schema)
        if not re.match(r"^trl_chk_[0-9A-HJKMNP-TV-Z]{10,}$", checklist_id):
            _log("VALIDATION_ERROR", "checklist_id is not in the expected format", field="checklist_id")
            return _err("VALIDATION_ERROR", "checklist_id is not in the expected format", field="checklist_id")
        if not re.match(r"^trl_itm_[0-9A-HJKMNP-TV-Z]{10,}$", checkitem_id):
            _log("VALIDATION_ERROR", "checkitem_id is not in the expected format", field="checkitem_id")
            return _err("VALIDATION_ERROR", "checkitem_id is not in the expected format", field="checkitem_id")

        if name is None and checked is None and pos is None:
            _log("VALIDATION_ERROR", "No updatable fields provided (provide at least one of name, checked, pos)")
            return _err("VALIDATION_ERROR", "No updatable fields provided (provide at least one of name, checked, pos)")

        if name is not None:
            if not isinstance(name, str):
                _log("VALIDATION_ERROR", "name must be a string", field="name")
                return _err("VALIDATION_ERROR", "name must be a string", field="name")
            if name.strip() == "":
                _log("VALIDATION_ERROR", "name must be non-empty", field="name")
                return _err("VALIDATION_ERROR", "name must be non-empty", field="name")

        if checked is not None and not isinstance(checked, bool):
            _log("VALIDATION_ERROR", "checked must be a boolean", field="checked")
            return _err("VALIDATION_ERROR", "checked must be a boolean", field="checked")

        if pos is not None:
            if not isinstance(pos, (int, float)) or isinstance(pos, bool):
                _log("VALIDATION_ERROR", "pos must be a number", field="pos")
                return _err("VALIDATION_ERROR", "pos must be a number", field="pos")
            if pos < 0:
                _log("VALIDATION_ERROR", "pos must be >= 0", field="pos")
                return _err("VALIDATION_ERROR", "pos must be >= 0", field="pos")

        checklists = _load("trello_checklists.json")
        if not isinstance(checklists, list):
            checklists = []
        items = _load("trello_checkitems.json")
        if not isinstance(items, list):
            items = []

        checklist = next((c for c in checklists if isinstance(c, dict) and c.get("id") == checklist_id), None)
        if checklist is None:
            _log("NOT_FOUND", "Checklist not found", field="checklist_id")
            return _err("NOT_FOUND", "Checklist not found", field="checklist_id")

        if checklist.get("status") != "active":
            _log("CONFLICT", "Checklist is deleted; checkitems are not operable once the checklist is deleted", field="checklist_id")
            return _err("CONFLICT", "Checklist is deleted; checkitems are not operable once the checklist is deleted", field="checklist_id")

        item = next((it for it in items if isinstance(it, dict) and it.get("id") == checkitem_id), None)
        if item is None:
            _log("NOT_FOUND", "Checkitem not found", field="checkitem_id")
            return _err("NOT_FOUND", "Checkitem not found", field="checkitem_id")

        # Verify ownership
        if item.get("checklist_id") != checklist_id:
            _log("NOT_FOUND", "Checkitem is not a member of the specified checklist (ownership check failed)", field="checkitem_id")
            return _err("NOT_FOUND", "Checkitem is not a member of the specified checklist (ownership check failed)", field="checkitem_id")

        if item.get("status") != "active":
            _log("CONFLICT", "Checkitem is deleted and cannot be updated", field="checkitem_id")
            return _err("CONFLICT", "Checkitem is deleted and cannot be updated", field="checkitem_id")

        # Apply updates
        changed = False
        if name is not None and item.get("name") != name:
            item["name"] = name
            changed = True
        if checked is not None and item.get("checked") != checked:
            item["checked"] = checked
            changed = True
        if pos is not None and item.get("pos") != pos:
            item["pos"] = pos
            changed = True

        if not changed:
            # idempotent success: record access/update attempt but return the resource unchanged
            _log("OK", "No changes applied (idempotent)", checklist_id=checklist_id, checkitem_id=checkitem_id)
            return {"checkitem": item, "idempotent": True}

        item["updated_at"] = _now_iso()
        _save("trello_checkitems.json", items)

        _log("OK", "Updated checkitem", checklist_id=checklist_id, checkitem_id=checkitem_id)
        return {"checkitem": item}
    except Exception as e:
        _log("ERROR", "Internal error", detail=str(e))
        return _err("CONFLICT", "Internal error")

