def update_board(board_id, name=None, desc=None, closed=None, status=None, **_extra):
    import json, os, datetime, re, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0243000" if __import__("os").path.isdir("./environment_mix/0243000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_board"

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _gen_id(prefix):
        ts = int(time.time() * 1000)
        r = random.getrandbits(80)
        def enc(v, n):
            s = []
            for _ in range(n):
                s.append(_B32[v & 31])
                v >>= 5
            return "".join(reversed(s))
        return prefix + enc(ts, 10) + enc(r, 16)

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, message=None, **extra):
        logs = _load("trello_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_id("trl_req_"),
            "endpoint": endpoint,
            "status": status_code,
            "message": message,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        row.update(extra)
        logs.append(row)
        _save("trello_request_logs.json", logs)

    if not isinstance(board_id, str) or not re.match(r"^trl_brd_[0-9A-HJKMNP-TV-Z]{10,}$", board_id):
        _log("VALIDATION_ERROR", "Invalid board_id format", field="board_id")
        return _err("VALIDATION_ERROR", "Invalid board_id format", field="board_id")

    if all(v is None for v in (name, desc, closed, status)):
        _log("VALIDATION_ERROR", "No updatable fields provided")
        return _err("VALIDATION_ERROR", "No updatable fields provided")

    if name is not None:
        if not isinstance(name, str) or name.strip() == "":
            _log("VALIDATION_ERROR", "name must be a non-empty string", field="name")
            return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")
        name = name.strip()

    if desc is not None and not (isinstance(desc, str) or desc is None):
        _log("VALIDATION_ERROR", "desc must be a string or null", field="desc")
        return _err("VALIDATION_ERROR", "desc must be a string or null", field="desc")

    if closed is not None and not isinstance(closed, bool):
        _log("VALIDATION_ERROR", "closed must be boolean", field="closed")
        return _err("VALIDATION_ERROR", "closed must be boolean", field="closed")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            _log("VALIDATION_ERROR", "status must be one of: active, archived, deleted", field="status")
            return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted", field="status")

    boards = _load("trello_boards.json")
    if not isinstance(boards, list):
        boards = []
    idx = None
    brd = None
    for i, r in enumerate(boards):
        if isinstance(r, dict) and r.get("id") == board_id:
            idx = i
            brd = r
            break
    if brd is None:
        _log("NOT_FOUND", "Board not found", board_id=board_id)
        return _err("NOT_FOUND", "Board not found", board_id=board_id)

    # lifecycle transitions
    transitions = {"active": ("archived", "deleted"), "archived": ("active", "deleted"), "deleted": ()}
    cur_status = brd.get("status")
    target_status = cur_status

    if status is not None and status != cur_status:
        if cur_status not in transitions or status not in transitions[cur_status]:
            _log("INVALID_TRANSITION", "Illegal status transition", from_status=cur_status, to_status=status)
            return _err("INVALID_TRANSITION", f"Illegal status transition from '{cur_status}' to '{status}'", field="status")
        target_status = status

    target_closed = brd.get("closed")
    if closed is not None:
        target_closed = closed

    # enforce coupling closed<->status per constraints:
    # closed=true implies status in ('archived','deleted'); closed=false implies status='active'
    if target_closed is True and target_status == "active":
        # coerce to archived if possible
        if cur_status == "active":
            target_status = "archived"
        elif cur_status == "archived":
            target_status = "archived"
    if target_closed is False and target_status != "deleted":
        # must be active
        if cur_status == "archived":
            target_status = "active"
        elif cur_status == "active":
            target_status = "active"

    # Validate computed transition legality
    if target_status != cur_status:
        if cur_status not in transitions or target_status not in transitions[cur_status]:
            _log("INVALID_TRANSITION", "Illegal status transition (computed)", from_status=cur_status, to_status=target_status)
            return _err("INVALID_TRANSITION", f"Illegal status transition from '{cur_status}' to '{target_status}'", field="status")

    updated = dict(brd)
    if name is not None:
        updated["name"] = name
    if desc is not None:
        updated["desc"] = desc
    updated["status"] = target_status

    # align closed with status
    if updated["status"] == "active":
        updated["closed"] = False
    elif updated["status"] in ("archived", "deleted"):
        updated["closed"] = True

    updated["updated_at"] = _now_iso()

    boards[idx] = updated
    _save("trello_boards.json", boards)
    _log("OK", "updated", board_id=board_id)
    return {"board": updated}
